import {
  AfterViewInit,
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  EventEmitter,
  Input,
  OnChanges,
  OnDestroy,
  Output,
  SimpleChanges,
  ViewChild
} from '@angular/core';

/**
 * Thin Angular wrapper around vanilla-jsoneditor (tree mode).
 * The library is Svelte-compiled and framework-agnostic; it is lazy-imported
 * so it only loads when the Advanced tab is opened.
 */
@Component({
  selector: 'app-vanilla-json-editor',
  standalone: true,
  template: `<div #editorContainer class="vanilla-editor-container"></div>`,
  styles: [`
    .vanilla-editor-container {
      height: 500px;

      :host ::ng-deep {
        .jse-main {
          min-height: 500px;
        }
      }
    }
  `],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class VanillaJsonEditorComponent implements AfterViewInit, OnDestroy, OnChanges {
  @ViewChild('editorContainer') editorContainer!: ElementRef<HTMLElement>;

  @Input() content: unknown = {};
  @Input() readOnly = false;
  @Output() contentChange = new EventEmitter<unknown>();

  private editor: any = null;
  private initialized = false;
  private suppressChange = false;

  async ngAfterViewInit(): Promise<void> {
    const { createJSONEditor } = await import('vanilla-jsoneditor');

    this.editor = createJSONEditor({
      target: this.editorContainer.nativeElement,
      props: {
        content: { json: this.content },
        mode: 'tree',
        readOnly: this.readOnly,
        onChange: (updatedContent: any) => {
          if (this.suppressChange) return;
          const data = updatedContent.json !== undefined
            ? updatedContent.json
            : JSON.parse(updatedContent.text);
          this.contentChange.emit(data);
        }
      }
    });

    this.initialized = true;
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (!this.initialized || !this.editor) return;

    if (changes['content']) {
      this.suppressChange = true;
      this.editor.update({ content: { json: this.content } });
      this.suppressChange = false;
    }

    if (changes['readOnly']) {
      this.editor.updateProps({ readOnly: this.readOnly });
    }
  }

  ngOnDestroy(): void {
    if (this.editor) {
      this.editor.destroy();
      this.editor = null;
    }
  }
}
